{{!-- Styling parameters: class, titleClass, gridClass, cardClass, cardTitleClass, imageClass, contentClass, descriptionClass --}}
{{#with this as |ghostcnStyles|}}
{{!-- Use inside {{#post}}. heading overrides the section title. Empty results render nothing. --}}
{{#if primary_tag}}
{{#get "posts" filter="id:-{{id}}+tag:{{primary_tag.slug}}" limit="3" include="tags,authors"}}{{#if posts}}
<section class="ghcn-related{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" aria-label="Related posts">
  <h2 class="ghcn-related__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">{{#if ghostcnStyles.heading}}{{ghostcnStyles.heading}}{{else}}Keep reading{{/if}}</h2>
  <div class="ghcn-related__grid{{#if ghostcnStyles.gridClass}} {{ghostcnStyles.gridClass}}{{/if}}">
    {{#foreach posts}}
    <article class="ghcn-related__card{{#if ghostcnStyles.cardClass}} {{ghostcnStyles.cardClass}}{{/if}}">
      {{#if feature_image}}<a class="ghcn-related__image-link" href="{{url}}" tabindex="-1" aria-hidden="true"><img class="ghcn-related__image{{#if ghostcnStyles.imageClass}} {{ghostcnStyles.imageClass}}{{/if}}" src="{{img_url feature_image size="m"}}" alt="" loading="lazy" /></a>{{/if}}
      <div class="ghcn-related__content{{#if ghostcnStyles.contentClass}} {{ghostcnStyles.contentClass}}{{/if}}"><h3 class="ghcn-related__card-title{{#if ghostcnStyles.cardTitleClass}} {{ghostcnStyles.cardTitleClass}}{{/if}}"><a href="{{url}}">{{title}}</a></h3><p class="ghcn-related__description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{excerpt words="20"}}</p></div>
    </article>
    {{/foreach}}
  </div>
</section>
{{/if}}{{/get}}
{{else}}
{{#get "posts" filter="id:-{{id}}" limit="3" include="tags,authors"}}{{#if posts}}
<section class="ghcn-related{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" aria-label="Related posts">
  <h2 class="ghcn-related__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">{{#if ghostcnStyles.heading}}{{ghostcnStyles.heading}}{{else}}Keep reading{{/if}}</h2>
  <div class="ghcn-related__grid{{#if ghostcnStyles.gridClass}} {{ghostcnStyles.gridClass}}{{/if}}">
    {{#foreach posts}}
    <article class="ghcn-related__card{{#if ghostcnStyles.cardClass}} {{ghostcnStyles.cardClass}}{{/if}}">
      {{#if feature_image}}<a class="ghcn-related__image-link" href="{{url}}" tabindex="-1" aria-hidden="true"><img class="ghcn-related__image{{#if ghostcnStyles.imageClass}} {{ghostcnStyles.imageClass}}{{/if}}" src="{{img_url feature_image size="m"}}" alt="" loading="lazy" /></a>{{/if}}
      <div class="ghcn-related__content{{#if ghostcnStyles.contentClass}} {{ghostcnStyles.contentClass}}{{/if}}"><h3 class="ghcn-related__card-title{{#if ghostcnStyles.cardTitleClass}} {{ghostcnStyles.cardTitleClass}}{{/if}}"><a href="{{url}}">{{title}}</a></h3><p class="ghcn-related__description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{excerpt words="20"}}</p></div>
    </article>
    {{/foreach}}
  </div>
</section>
{{/if}}{{/get}}
{{/if}}
{{/with}}

.ghcn-related { margin-block: 2em; color: var(--foreground); }
.ghcn-related__title { margin: 0 0 1em; font-size: 1.5em; line-height: 1.2; }
.ghcn-related__grid { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 1em; }
.ghcn-related__card { min-width: 0; overflow: hidden; background: var(--card); color: var(--card-foreground); border: 1px solid var(--border); border-radius: var(--radius); }
.ghcn-related__image-link { display: block; aspect-ratio: 16/9; overflow: hidden; }
.ghcn-related__image { display: block; width: 100%; height: 100%; object-fit: cover; }
.ghcn-related__content { padding: 1.25em; }
.ghcn-related__card-title { font-size: 1.125em; line-height: 1.3; margin: 0 0 .75em; }
.ghcn-related__card-title a { color: inherit; text-decoration: none; }
.ghcn-related__card-title a:hover { text-decoration: underline; }
.ghcn-related__description { color: var(--muted-foreground); font-size: .875em; margin: 0; }
.ghcn-related a:focus-visible { outline: 2px solid var(--ring); outline-offset: 3px; }
@media(max-width:760px) { .ghcn-related__grid { grid-template-columns: 1fr; } }
